/*getBuyerPrRecvSql*/
SELECT (ROWNUM ) No, -- 0 S.REQ_DEPT, -- 1 S.PR_NO, -- 2 S.BUYER_ITEM_NO, -- 3 S.CHANGE_DATE, -- 4 S.DESCRIPTION, -- 5 S.SPECIFICATION, -- 6 S.UNIT_MEASURE, -- 7 S.TARGET_QTY, -- 8 S.UNIT_PRICE, -- 9 S.AMT, -- 10 S.RD_DATE, -- 11 S.AGENT_NAME, -- 12 S.REF_PR_NO, -- 13 S.GUYLJAE_FLAG , -- 14 S.PAY_TERMS, -- 15 S.PR_SEQ, -- 16 S.BDGT_FLAG, -- 17 S.FIXED_PRICE_FLAG, -- 18 S.ACCOUNT_TYPE, -- 19 S.BUYER, -- 20 S.BYIT_COMORG_CODE, -- 21 S.CONTRACT_NO, -- 22 S.CONTRACT_SEQ, -- 23 S.DOC_TYPE, -- 24 S.AGENT_CODE, -- 25 S.CHANGE_USER_DEPT, -- 26 S.BUDGET_DEPT, -- 27 S.PLAN_AMT_FLAG, -- 28 S.RECV_QTY, -- 29 S.RETURN_REASON, -- 30 S.REMARK, -- 31 S.REF_PR_TEXT, -- 31 S.RECV_FLAG, --32 S.HD_REMARK, --33 S.ADD_USER_ID, S.ADD_USER_NAME, (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = S.BUYER) AS BUYER_NAME_LOC, (SELECT DECODE(COUNT(COMPANY),'0','N','Y') FROM ICOGPASS PASS WHERE PASS.COMPANY =S.BUYER AND PASS.DOCU_TYPE = 'PX' ) AS PASS_YN, (SELECT DECODE(COUNT(COD2.CODE),0,'Y','N') FROM ICOMCOD2 COD2 WHERE COD2.COMPANY_CODE = #{comCode} AND COD2.TYPE = 'EXCF' AND COD2.FLAG = 'Y' AND COD2.CODE = S.BUYER AND COD2.TEXT1 = #{userID} ) AS CONFIRM_YN, S.DELY_TO_LOCATION_TEXT, S.ADD_USER_TEL, S.CARD_USE_FLAG, S.BUDGET_DEPT_NAME, S.ACCOUNT_NAME, S.CATEGORY_NO, S.PR_LIST_PRICE, S.PR_TARGET_PRICE FROM ( SELECT ROWNUM NUM, X.REQ_DEPT, X.PR_NO, X.BUYER_ITEM_NO, X.CHANGE_DATE, X.DESCRIPTION, X.SPECIFICATION, X.UNIT_MEASURE, X.TARGET_QTY, X.UNIT_PRICE, X.AMT, X.RD_DATE, X.AGENT_NAME, X.REF_PR_NO, X.GUYLJAE_FLAG , X.PAY_TERMS, X.PR_SEQ, X.BDGT_FLAG, X.FIXED_PRICE_FLAG, X.ACCOUNT_TYPE, X.BUYER, X.BYIT_COMORG_CODE, X.CONTRACT_NO, X.CONTRACT_SEQ, X.DOC_TYPE, X.AGENT_CODE, X.CHANGE_USER_DEPT, X.BUDGET_DEPT, X.PLAN_AMT_FLAG, X.RECV_QTY, X.RETURN_REASON, X.REMARK, X.REF_PR_TEXT, X.RECV_FLAG, X.HD_REMARK, X.ADD_USER_ID, X.ADD_USER_NAME, X.DELY_TO_LOCATION_TEXT, X.ADD_USER_TEL, X.CARD_USE_FLAG, X.BUDGET_DEPT_NAME, X.ACCOUNT_NAME, X.CATEGORY_NO, X.PR_LIST_PRICE, X.PR_TARGET_PRICE FROM ( SELECT (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = A.BUYER AND CODE = A.CHANGE_USER_DEPT ) AS REQ_DEPT, -- 1 A.PR_NO, -- 2 A.BUYER_ITEM_NO BUYER_ITEM_NO, -- 3 A.CHANGE_DATE CHANGE_DATE, -- 4 A.DESCRIPTION DESCRIPTION, -- 5 A.SPECIFICATION SPECIFICATION, -- 6 A.UNIT_MEASURE UNIT_MEASURE, -- 7 NVL(A.TARGET_QTY,0) TARGET_QTY, -- 8 NVL(E.UNIT_PRICE,0) UNIT_PRICE, -- 9 DECODE(NVL(A.RECV_QTY,0),0,A.TARGET_QTY,A.RECV_QTY) * NVL(E.UNIT_PRICE,0) AMT, -- 10 A.RD_DATE RD_DATE, -- 11 DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = A.BUYER), 'N', '코리아이플랫폼(주)', (SELECT DECODE(AGENT_OPEN_FLAG,'N','코리아이플랫폼(주)',COM_NAME_LOC) FROM ICOMCMPY WHERE COM_CODE =E.AGENT)) AS AGENT_NAME, -- 12 A.REF_PR_NO REF_PR_NO, -- 13 DECODE(B.COM_CODE,NULL,'N','Y') GUYLJAE_FLAG, -- 14 E.PAY_TERMS PAY_TERMS, -- 15 A.PR_SEQ, -- 16 (SELECT Z.FLAG FROM ICOMCOD2 Z WHERE Z.TYPE = 'Z014' AND Z.COMPANY_CODE = A.BUYER AND Z.CODE = A.ACCOUNT_TYPE) BDGT_FLAG, -- 17 C.FIXED_PRICE_FLAG FIXED_PRICE_FLAG, -- 18 DECODE(A.BUDGET_DEPT,NULL,C.ACCOUNT_TYPE,A.ACCOUNT_TYPE) ACCOUNT_TYPE, -- 19 A.BUYER BUYER, -- 20 A.BYIT_COMORG_CODE BYIT_COMORG_CODE, -- 21 A.CONTRACT_NO CONTRACT_NO, -- 22 A.CONTRACT_SEQ CONTRACT_SEQ, -- 23 F.DOC_TYPE, -- 24 DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = A.BUYER), 'N', 'KRKORE0001', (SELECT DECODE(AGENT_OPEN_FLAG,'N','KRKORE0001',COM_CODE) FROM ICOMCMPY WHERE COM_CODE =E.AGENT)) AS AGENT_CODE, -- 25 A.CHANGE_USER_DEPT, -- 26 A.BUDGET_DEPT, -- 27 A.PLAN_AMT_FLAG, -- 28 DECODE(NVL(A.RECV_QTY,0),0,A.TARGET_QTY,A.RECV_QTY) AS RECV_QTY, -- 29 A.RETURN_REASON, -- 30 TRIM(A.REMARK) AS REMARK, -- 31 (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND TYPE ='M014' AND CODE = A.REF_PR_NO) AS REF_PR_TEXT, -- 32 A.RECV_FLAG, F.REMARK AS HD_REMARK, A.ADD_USER_ID, A.ADD_USER_NAME, A.DELY_TO_LOCATION_TEXT, A.ADD_USER_TEL, F.CARD_USE_FLAG, NVL((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND TYPE = 'C001' AND CODE = A.BUDGET_DEPT),'') AS BUDGET_DEPT_NAME, NVL((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND TYPE = 'Z014' AND CODE = A.ACCOUNT_TYPE),'') AS ACCOUNT_NAME, C.CATEGORY_NO, A.LIST_PRICE AS PR_LIST_PRICE, A.TARGET_PRICE AS PR_TARGET_PRICE FROM ICOMPRDT A , ICOMTRGW B, ICOMBYIT C, ICOMCQDT E , ICOMPRHD F WHERE A.RECV_FLAG = 'GA' AND A.SAVE_FLAG = 'PR' AND A.ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y')
AND A.BUYER = #{st_com_code2}
AND A.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')
AND A.BUYER = #{st_buyer}
--콘티넨탈(KRCONT0006)일경우, icomcod2에 등록된 cost center별 담당자가 본인인 건만 조회되게 한다.
AND CASE WHEN A.BUYER ='KRCONT0006' THEN '1' ELSE A.PURCHASER_DEPT END = CASE WHEN A.BUYER ='KRCONT0006' THEN ( SELECT to_char(count(*)) FROM ICOMCOD2 X WHERE 1=1 AND X.TYPE ='M014' AND NVL(X.FLAG,'Y') = 'Y' AND X.CODE = A.REF_PR_NO AND X.COMPANY_CODE = A.BUYER AND X.TEXT4 = #{userID} ) ELSE #{userDept} END
AND A.CHANGE_USER_DEPT = #{st_req_dept_code}
AND A.PR_NO = #{st_pr_no}
AND A.ADD_USER_NAME = #{st_add_user_name}
AND (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND TYPE ='M014' AND CODE = A.REF_PR_NO) LIKE '%'|| #{st_search_code} ||'%'
AND A.REF_PR_NO = #{st_search_code}
AND C.CATEGORY_NO IN ( SELECT STD_CATEG_ID FROM ICOMBYCA WHERE com_code = A.BUYER AND CATEG_NAME = #{st_search_code} )
AND C.DESCRIPTION_LOC LIKE '%'||#{st_search_code}||'%'
AND A.BUYER = F.BUYER AND A.PR_NO = F.PR_NO AND A.BUYER = B.COM_CODE(+) AND A.PR_NO = B.KEY_1(+) AND A.BYIT_COMORG_CODE = C.BUYER AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.BYIT_COMORG_CODE = E.BUYER AND A.BUYER_ITEM_NO = E.BUYER_ITEM_NO AND A.CONTRACT_NO = E.CONTRACT_NO AND A.CONTRACT_SEQ = E.CONTRACT_SEQ AND E.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND E.BUYER = C.BUYER AND A.STATUS <> 'D' AND E.STATUS <> 'D' AND F.STATUS <> 'D' AND C.STATUS <> 'D' AND C.PRODUCT_CLOSE_FLAG = 'N'
ORDER BY ${st_sort_column} ${st_sort_flag}
ORDER BY A.PR_NO DESC, A.PR_SEQ
) X
)S



		/*getDeptCombo*/

                 SELECT CODE, TEXT1 
                 FROM ICOMCOD2 
                 where COMPANY_CODE = #{company_code}        
                 AND TYPE = 'C001' 
