/*setTransfer*/

 UPDATE ICOMPRDT SET PURCHASER_DEPT = #{PURCHASER_DEPT}                
 WHERE BUYER = #{BUYER} 									  
   AND PR_NO = #{PR_NO}  AND PR_SEQ = #{PR_SEQ}

/*setPxPrPoUpdate1*/
UPDATE ICOMPRDT A SET STATUS = 'R', REF_ADD_USER_ID = #{USERID} , PURCHASER_ID = #{USERID} ,
RECV_QTY = A.TARGET_QTY, -- 직발주
RECV_QTY = #{RECV_QTY} , -- 구매요청접수 발주 화면에서 발주 PO_REMARK = ltrim(#{PO_REMARK} ), -- 발주비고내용
RD_DATE = #{RD_DATE} , RECV_FLAG = #{RECV_FLAG} , SAVE_FLAG = 'PX', REF_NO = #{PX_NO} , REF_SEQ = lpad(#{PX_SEQ}, 6 ,'0'), RETURN_REASON = ltrim(#{RETURN_REASON} ) -- 요청수량 변경사유는 ICOMPRDT.RETURN_REASON 적용
WHERE A.BUYER = #{BUYER} -- 반려 사유는 ICOMPRDT.RETURN_REASON , ICOMPRHD.RETURN_REASON 적용 AND A.PR_NO = #{PR_NO} AND A.PR_SEQ = #{PR_SEQ}



			/*setNewProxyPoCreate4*/

         UPDATE ICOMPRDT  SET PO_QTY = #{RECV_QTY}      
                WHERE BUYER = #{BUYER}      
                AND   PR_NO =  #{PR_NO}      
                AND   PR_SEQ = TO_CHAR(#{PR_SEQ}     ,'FM000000')

/*getTempBdgtUpdateInsertMergePxPo1*/
UPDATE ICOMBDGT A SET A.TEMP_AMT = NVL(A.TEMP_AMT +
(SELECT NVL(SUM(B.UNIT_PRICE*C.RECV_QTY) - SUM(C.TARGET_PRICE*C.TARGET_QTY),0) FROM ICOMCQDT B, ICOMPRDT C WHERE A.BUYER = C.BUYER AND C.REF_NO = #{REF_NO} AND C.BUDGET_DEPT||C.ACCOUNT_TYPE = A.DEPT||A.ACCOUNT_TYPE AND B.BUYER = C.BYIT_COMORG_CODE AND B.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND B.CONTRACT_NO = C.CONTRACT_NO AND B.CONTRACT_SEQ = C.CONTRACT_SEQ AND C.PLAN_AMT_FLAG = 'Y' AND C.RECV_FLAG NOT IN ('GR','PR') GROUP BY C.BUDGET_DEPT , C.ACCOUNT_TYPE ) , 0 ) WHERE BUYER = #{BUYER} AND DEPT||ACCOUNT_TYPE IN ( SELECT BUDGET_DEPT||ACCOUNT_TYPE FROM ICOMPRDT T WHERE T.BUYER = A.BUYER AND T.REF_NO = #{REF_NO} AND T.PLAN_AMT_FLAG = 'Y' GROUP BY BUDGET_DEPT , ACCOUNT_TYPE ) AND (SELECT MAX(ADD_DATE) FROM ICOMPRDT WHERE BUYER = #{BUYER} AND REF_NO = #{REF_NO} ) BETWEEN A.FROM_DATE AND A.TO_DATE

/*updateGetBdgtAmtCheckFinal*/
UPDATE ICOMPRDT SET RECV_QTY = #{RECV_QTY}, --1 ACCOUNT_TYPE = #{ACCOUNT_TYPE}, --2 BUDGET_DEPT = #{BUDGET_DEPT} --3
WHERE BUYER = #{BUYER} --4 AND PR_NO = #{PR_NO} --5 AND PR_SEQ =#{PR_SEQ} --6

/*updateGetBdgtAmtDetailCheckFinal*/
UPDATE ICOMPRDT SET RECV_QTY = #{RECV_QTY}, --1 ACCOUNT_TYPE = #{ACCOUNT_TYPE}, --2 BUDGET_DEPT = #{BUDGET_DEPT} --3
WHERE BUYER = #{BUYER} --4 AND PR_NO = #{PR_NO} --5 AND PR_SEQ =#{PR_SEQ} --6

