/*getBdgtAmtCheckFinal*/
SELECT /*+USE_NL(Y X)*/ (SELECT C.TEXT2 FROM ICOMCOD2 C WHERE C.TYPE = 'Z014' AND C.COMPANY_CODE = X.BUYER AND C.CODE = X.ACCOUNT_TYPE ) ACCOUNT_TYPE_TEXT, --0 Y.PLAN_AMT, --1 Y.RESULT_AMT, --2 Y.TEMP_AMT, --3 X.TOT_AMT, --4 DECODE(SIGN(Y.PLAN_AMT - (Y.RESULT_AMT + Y.TEMP_AMT + X.TOT_AMT)), -1 ,'예산초과','예산적용') BUYER_CHECK, --5 X.BUDGET_DEPT , --6 X.ACCOUNT_TYPE, --7 (SELECT TEXT1 FROM ICOMCOD2 A WHERE A.COMPANY_CODE = X.BUYER AND A.CODE = X.BUDGET_DEPT AND A.TYPE = 'C001' ) AS BUDGET_DEPT_NAME --8 FROM (SELECT /*+USE_NL(A B) USE_NL(A C)*/ MAX(A.BUYER) BUYER, A.BUDGET_DEPT , A.ACCOUNT_TYPE,
SUM(( DECODE(A.RECV_QTY,0,1,NVL(A.RECV_QTY,1))) * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.TARGET_PRICE,0),NVL(C.UNIT_PRICE,0))) TOT_AMT
-- SUM((DECODE(A.RECV_QTY,0,1,NVL(A.RECV_QTY,1))-A.TARGET_QTY * -- DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.TARGET_PRICE,0),NVL(C.UNIT_PRICE,0)))) TOT_AMT -- 20140919 예산SQL변경
SUM( ((DECODE(A.RECV_QTY,0,1,NVL(A.RECV_QTY,1)) - A.TARGET_QTY) * A.TARGET_PRICE)) TOT_AMT
FROM ICOMPRDT A, ICOMBYIT B, ICOMCQDT C WHERE A.BUYER = #{BUYER}
AND A.PR_NO||A.PR_SEQ IN
#{item}
AND A.BYIT_COMORG_CODE = B.BUYER AND B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG = 'N' AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ GROUP BY A.BUDGET_DEPT , A.ACCOUNT_TYPE ) X , ICOMBDGT Y WHERE X.BUYER = Y.BUYER AND X.BUDGET_DEPT = Y.DEPT AND X.ACCOUNT_TYPE = Y.ACCOUNT_TYPE AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN Y.FROM_DATE AND Y.TO_DATE

/*getBdgtAmtCheckFinal*/
SELECT /*+USE_NL(Y X)*/ (SELECT C.TEXT2 FROM ICOMCOD2 C WHERE C.TYPE = 'Z014' AND C.COMPANY_CODE = X.BUYER AND C.CODE = X.ACCOUNT_TYPE ) ACCOUNT_TYPE_TEXT, --0 Y.PLAN_AMT, --1 Y.RESULT_AMT, --2 Y.TEMP_AMT, --3 X.TOT_AMT, --4 DECODE(SIGN(Y.PLAN_AMT - (Y.RESULT_AMT + Y.TEMP_AMT + X.TOT_AMT)), -1 ,'예산초과','예산적용') BUYER_CHECK, --5 X.BUDGET_DEPT , --6 X.ACCOUNT_TYPE, --7 (SELECT TEXT1 FROM ICOMCOD2 A WHERE A.COMPANY_CODE = X.BUYER AND A.CODE = X.BUDGET_DEPT AND A.TYPE = 'C001' ) AS BUDGET_DEPT_NAME --8 FROM (SELECT /*+USE_NL(A B) USE_NL(A C)*/ MAX(A.BUYER) BUYER, A.BUDGET_DEPT , A.ACCOUNT_TYPE,
SUM(( DECODE(A.RECV_QTY,0,1,NVL(A.RECV_QTY,1))) * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.TARGET_PRICE,0),NVL(C.UNIT_PRICE,0))) TOT_AMT
-- SUM((DECODE(A.RECV_QTY,0,1,NVL(A.RECV_QTY,1))-A.TARGET_QTY * -- DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.TARGET_PRICE,0),NVL(C.UNIT_PRICE,0)))) TOT_AMT -- 20140919 예산SQL변경
SUM( ((DECODE(A.RECV_QTY,0,1,NVL(A.RECV_QTY,1)) - A.TARGET_QTY) * A.TARGET_PRICE)) TOT_AMT
FROM ICOMPRDT A, ICOMBYIT B, ICOMCQDT C ,ICOMCMPY D WHERE A.BUYER = D.COM_CODE AND D.BUDGET_FLAG = 'Y'
AND A.BUYER IN
#{item}
AND A.BUDGET_DEPT IN
#{item}
AND A.ACCOUNT_TYPE IN
#{item}
AND A.BYIT_COMORG_CODE = B.BUYER AND B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG = 'N' AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ GROUP BY A.BUDGET_DEPT , A.ACCOUNT_TYPE ) X , ICOMBDGT Y WHERE X.BUYER = Y.BUYER AND X.BUDGET_DEPT = Y.DEPT AND X.ACCOUNT_TYPE = Y.ACCOUNT_TYPE AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN Y.FROM_DATE AND Y.TO_DATE


		/*"selectICOMPRDTCheck"*/

		 SELECT  COUNT(1) CNT FROM ICOMPRDT             
		    WHERE BUYER = #{BUYER}
		        AND PR_NO = #{PR_NO}    
                AND PR_SEQ =  #{PR_SEQ}     
                AND SAVE_FLAG  = 'PR'


		/*"selectICOMPRDTCheck2"*/

		 SELECT  COUNT(1) CNT FROM ICOMPRDT             
		    WHERE BUYER = #{BUYER}
		        AND PR_NO = #{PR_NO}    
                AND PR_SEQ =  #{PR_SEQ}     
                AND RECV_FLAG      = 'RR'                                   
                AND STATUS         = 'R'

/*selectHongikList*/
SELECT ROWNUM NUM ,X.BUYER ,X.PR_NO ,X.DESCRIPTION ,X.TOT_QTY ,X.REF_PR_TEXT ,X.REQ_DEPT ,X.ADD_DATE ,X.TOT_AMT ,X.REF_PR_NO ,X.CHANGE_USER_DEPT FROM ( SELECT A.BUYER BUYER ,A.PR_NO ,MAX(A.DESCRIPTION) AS DESCRIPTION ,COUNT(A.PR_SEQ)-1 AS TOT_QTY ,MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = C.BUYER AND TYPE ='M014' AND CODE = A.REF_PR_NO)) AS REF_PR_TEXT ,MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = A.BUYER AND CODE = A.CHANGE_USER_DEPT )) AS REQ_DEPT ,MAX(A.ADD_DATE) ADD_DATE ,SUM((DECODE(NVL(A.RECV_QTY,0),0,A.TARGET_QTY,A.RECV_QTY) * NVL(E.UNIT_PRICE,0))) AS TOT_AMT ,MAX(A.REF_PR_NO) AS REF_PR_NO ,MAX(A.CHANGE_USER_DEPT) AS CHANGE_USER_DEPT FROM ICOMPRDT A , ICOMBYIT C, ICOMCQDT E WHERE A.BUYER = #{st_com_code} AND A.RECV_FLAG = 'GA' AND A.SAVE_FLAG = 'PR' AND A.ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND A.PURCHASER_DEPT = #{st_department}
AND A.CHANGE_USER_DEPT = #{st_req_dept_code}
AND A.PR_NO LIKE '%'||#{st_pr_no}||'%'
AND A.BYIT_COMORG_CODE = C.BUYER AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.BYIT_COMORG_CODE = E.BUYER AND A.BUYER_ITEM_NO = E.BUYER_ITEM_NO AND A.CONTRACT_NO = E.CONTRACT_NO AND A.CONTRACT_SEQ = E.CONTRACT_SEQ AND E.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND E.BUYER = C.BUYER AND A.STATUS <> 'D' AND E.STATUS <> 'D' AND C.STATUS <> 'D' AND C.PRODUCT_CLOSE_FLAG = 'N' GROUP BY A.BUYER, A.PR_NO ORDER BY A.BUYER, A.PR_NO ) X

/*selectMpPoOrdePrReqReceiptList*/
SELECT ROWNUM NUM ,X.BUYER ,X.PR_NO ,X.DESCRIPTION ,X.TOT_QTY ,X.REF_PR_TEXT ,X.REQ_DEPT ,X.ADD_DATE ,X.TOT_AMT ,X.REF_PR_NO ,X.CHANGE_USER_DEPT ,X.ADD_USER_ID ,(SELECT USER_NAME_LOC FROM ICOMLUSR A WHERE A.USER_ID = X.ADD_USER_ID) AS ADD_USER_NAME FROM ( SELECT A.BUYER BUYER ,A.PR_NO ,MAX(A.DESCRIPTION) AS DESCRIPTION ,COUNT(A.PR_SEQ)-1 AS TOT_QTY ,MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = C.BUYER AND TYPE ='M014' AND CODE = A.REF_PR_NO)) AS REF_PR_TEXT ,MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = A.BUYER AND CODE = A.CHANGE_USER_DEPT )) AS REQ_DEPT ,MAX(A.ADD_DATE) ADD_DATE ,SUM((DECODE(NVL(A.RECV_QTY,0),0,A.TARGET_QTY,A.RECV_QTY) * NVL(E.UNIT_PRICE,0))) AS TOT_AMT ,MAX(A.REF_PR_NO) AS REF_PR_NO ,MAX(A.CHANGE_USER_DEPT) AS CHANGE_USER_DEPT ,MAX(A.ADD_USER_ID) AS ADD_USER_ID FROM ICOMPRDT A , ICOMBYIT C, ICOMCQDT E WHERE A.BUYER = #{st_com_code} AND A.RECV_FLAG = 'GA' AND A.SAVE_FLAG = 'PR' AND A.ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND A.PURCHASER_DEPT = #{st_department}
AND A.CHANGE_USER_DEPT = #{st_req_dept_code}
AND A.PR_NO LIKE '%'||#{st_pr_no}||'%'
AND A.BYIT_COMORG_CODE = C.BUYER AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.BYIT_COMORG_CODE = E.BUYER AND A.BUYER_ITEM_NO = E.BUYER_ITEM_NO AND A.CONTRACT_NO = E.CONTRACT_NO AND A.CONTRACT_SEQ = E.CONTRACT_SEQ AND E.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND E.BUYER = C.BUYER AND A.STATUS <> 'D' AND E.STATUS <> 'D' AND C.STATUS <> 'D' AND C.PRODUCT_CLOSE_FLAG = 'N' GROUP BY A.BUYER, A.PR_NO ORDER BY A.BUYER, A.PR_NO ) X
